from pathlib import Path
import sys
sys.path.insert(0,str(Path(__file__).resolve().parent.parent))
from rendu import outils
base,p,c,h,w,table,liste,save=outils(2,12)
t=p('La prévention distingue l’apparition du syndrome, son repérage et la réduction de ses conséquences. La Ligue suisse contre le rhumatisme, dans sa publication de janvier 2023, indique qu’aucune mesure spécifique connue ne prévient la fibromyalgie ; les mesures générales proposées ne deviennent donc pas une garantie d’éviter la maladie.','f83-ligue-prevention','f83-ligue-bib')
t+=h('Prévention primaire : agir sur la santé sans promettre une protection spécifique')
t+=p('La Ligue recommande de traiter les maladies associées et de réduire les facteurs susceptibles de favoriser le syndrome, notamment en maîtrisant les douleurs d’un rhumatisme inflammatoire et en recherchant un soutien professionnel lors de stress prolongé. Elle conseille aussi l’arrêt du tabac et une alternance équilibrée entre tension et détente.','f83-ligue-prevention')
t+=p('Ces conseils concernent des situations à risque ou la santé générale ; ils ne définissent ni un test de susceptibilité ni un programme empêchant avec certitude la fibromyalgie. Le RCP rappelle que beaucoup de patients développent le syndrome sans événement déclencheur identifiable et que le stress n’est pas une explication obligatoire.','f83-ligue-prevention','f83-rcp-bps','f83-rcp-mecanismes')
t+=p('Les fréquences féminines et les estimations en population générale décrites au point 2 ne constituent pas des seuils de prévention individuelle. La possibilité d’atteinte chez les hommes ou les jeunes interdit de réserver toute vigilance aux seules femmes d’âge moyen.','f83-ligue-epidemiologie','f83-has-messages')
t+=h('Prévention secondaire : reconnaître tôt et conserver les diagnostics traitables')
t+=p('Chez une personne symptomatique, le clinicien recherche tôt la distribution, la durée, la fatigue et le sommeil non réparateur. Le RCP recommande un diagnostic aussi précoce que possible lorsque les critères sont remplis, avec une information compréhensible et un plan adapté.','f83-rcp-symptomes','f83-rcp-consultation')
t+=p('Le FIRST peut aider au repérage en soins primaires : au moins 5 éléments positifs sur 6 rendent la suspicion forte, sans remplacer le jugement clinique. La confirmation repose sur les critères révisés et le bilan minimal recommandé, afin d’éviter à la fois le sous-diagnostic et l’attribution excessive de symptômes à une fibromyalgie.','f83-has-orientation','f83-has-depistage','f83-rcp-criteres')
t+=p('Une réévaluation appropriée de tout symptôme nouveau protège contre l’ancrage diagnostique. Cette vigilance reste nécessaire même si le patient remplit toujours les critères du syndrome, puisque des maladies concomitantes peuvent apparaître ou devenir plus visibles.','f83-has-differentiel','f83-rcp-coexistence')
t+=h('Prévention tertiaire : limiter incapacité, isolement et iatrogénie')
t+=p('L’activité adaptée et son apprentissage en autonomie cherchent à préserver les capacités et la participation. Le programme s’ajuste à la tolérance, puis un relais aide à maintenir les bénéfices ; le clinicien ne prescrit pas une surenchère d’exercice lorsque le dosage aggrave les symptômes.','f83-has-activite','f83-has-programme','f83-has-relais')
t+=p('Le maintien de relations choisies, les groupes d’entraide et les associations de patients peuvent limiter l’isolement décrit par la Ligue. Le maintien dans l’emploi, avec des adaptations possibles, et une consultation sociale suisse constituent d’autres moyens concrets de préserver les rôles et d’examiner les démarches individuelles.','f83-ligue-relations','f83-ligue-prevention','f83-ligue-social')
t+=p('La surveillance du sommeil, de l’humeur et des médicaments réduit des conséquences évitables. Chaque renouvellement vérifie le bénéfice, la tolérance et le mésusage ; une idéation suicidaire ou une complication médicamenteuse modifie immédiatement la conduite au lieu d’être attribuée à la seule chronicité.','f83-has-sommeil','f83-has-humeur','f83-has-principes-med','aips-f83-dulox-interactions')
t+=table(['Niveau','Population et gestes concrets','Limite ou seuil réellement documenté'],[
['Primaire',p('Les personnes exposées à des douleurs inflammatoires ou à un stress prolongé reçoivent les soins appropriés ; les conseils de santé incluent arrêt du tabac et équilibre des activités.','f83-ligue-prevention'),p('Aucune mesure spécifique préventive n’est connue dans le document suisse consulté.','f83-ligue-prevention')],
['Secondaire',p('Les personnes présentant des douleurs diffuses chroniques bénéficient d’une évaluation clinique, d’un bilan minimal et de critères positifs.','f83-has-orientation','f83-has-depistage','f83-rcp-criteres'),p('Le seuil de FIRST reste une aide de suspicion ; la durée et les combinaisons WPI–SSS restent nécessaires pour la confirmation.','f83-has-orientation','f83-rcp-criteres')],
['Tertiaire',p('Les personnes diagnostiquées bénéficient d’un programme gradué, de relais sociaux et d’une réévaluation de chaque traitement.','f83-has-relais','f83-ligue-social','f83-has-principes-med'),p('Le suivi suit les objectifs et la tolérance ; aucun seuil biologique de guérison n’est proposé par les sources diagnostiques.','f83-has-suivi','f83-rcp-coexistence')]])
t+=p('Le choix de prévention reste ainsi lié au contexte épidémiologique sans transformer une prévalence mondiale en risque individuel suisse. La stratégie se juge sur le fonctionnement et la sécurité de la personne, avec des moyens ajustés à ses ressources.','f83-ligue-epidemiologie','f83-has-suivi','f83-has-annonce')
save(t)

base,p,c,h,w,table,liste,save=outils(2,13)
t=p('La fibromyalgie associe une douleur persistante et étendue à des symptômes de fatigue, de sommeil et de cognition, et son mécanisme nociplastique ne signifie ni douleur imaginaire ni inflammation musculaire obligatoire.','f83-rcp-definition','f83-rcp-mecanismes')
t+=p('Le diagnostic positif exige la combinaison WPI–SSS adéquate, une douleur généralisée dans au moins 4 des 5 régions et des symptômes présents depuis au moins 3 mois, tandis que mâchoire, thorax et abdomen comptent au WPI mais pas pour la généralisation.','f83-rcp-criteres','f83-rcp-annexe2016')
t+=p('Une parésie, une synovite, une atteinte respiratoire ou bulbaire, une urine foncée après effort ou un signe neurologique compressif impose la recherche et la prise en charge de la cause correspondante avant toute attribution au syndrome chronique.','p83-myofascial-fibro','f83-has-orientation','p83-myopathies-gravite','p83-rhabdo-clinique','p83-rhabdo-menace','pa17-lomb22-urgence')
t+=p('L’information, l’activité physique progressive adaptée et l’apprentissage de l’autogestion constituent le socle thérapeutique, et les objectifs suivent aussi la fonction, la participation et la qualité de vie.','f83-eular-strategie','f83-has-activite','f83-has-autogestion','f83-has-suivi')
t+=p('Une recommandation européenne ne crée pas une AMM suisse, et l’AIPS de Duloxétine axapharm n’autorise pas la fibromyalgie ; ses posologies de dépression ou d’anxiété gardent leurs indications propres.','aips-f83-dulox-indications','aips-f83-dulox-posologie','f83-has-antidepresseurs')
t+=p('Le clinicien réexamine tout symptôme nouveau, réévalue chaque médicament et organise le suivi avec les relais nécessaires, car une fibromyalgie reconnue ne protège ni d’une autre maladie ni d’une complication thérapeutique.','f83-has-differentiel','f83-has-principes-med','f83-has-coordination','aips-f83-dulox-interactions')
save(t)

base,p,c,h,w,table,liste,save=outils(2,14)
t=p('Les questions d’examen vérifient la distinction entre suspicion et confirmation, la portée des chiffres, la gravité et le statut suisse des prescriptions. Les réponses se fondent sur les critères retenus et les recommandations effectivement citées.','f83-rcp-criteres','f83-has-orientation','aips-f83-dulox-indications')
t+=table(['Question','Réponse correcte','Raison'],[
['Une forte douleur à de nombreux points suffit-elle ?',p('Non, le clinicien vérifie les combinaisons WPI–SSS, la généralisation et la durée des symptômes.','f83-rcp-criteres'),p('La sensibilité à la palpation ne remplace pas les critères diagnostiques actualisés.','p83-myofascial-fibro','f83-rcp-criteres')],
['Une douleur de mâchoire est-elle exclue de tous les calculs ?',p('Non, elle peut contribuer au WPI, mais elle est exclue du critère de douleur généralisée, comme le thorax et l’abdomen.','f83-rcp-annexe2016'),p('Le nombre de sites et le nombre de régions sont deux conditions différentes.','f83-rcp-annexe2016')],
['Les deux associations de seuils WPI–SSS s’additionnent-elles ?',p('Non, le patient remplit soit WPI au moins égal à 7 avec SSS au moins égal à 5, soit WPI de 4 à 6 avec SSS au moins égal à 9.','f83-rcp-criteres'),p('Le OU concerne cette alternative interne ; généralisation et durée restent nécessaires.','f83-rcp-criteres')],
['Un FIRST positif constitue-t-il le diagnostic ?',p('Non, le FIRST positif renforce la suspicion et le clinicien poursuit la confirmation et le bilan adapté.','f83-has-orientation','f83-has-depistage'),p('La HAS maintient la prépondérance du jugement clinique et demande le bilan minimal quel que soit le résultat du dépistage.','f83-has-orientation','f83-has-depistage')],
['Une polyarthrite interdit-elle le diagnostic de fibromyalgie ?',p('Non, les deux affections peuvent coexister et nécessitent une appréciation distincte.','f83-rcp-coexistence','f83-has-depistage'),p('Le clinicien ne confond ni hypersensibilité et synovite ni présence d’une comorbidité et exclusion du syndrome.','f83-has-orientation','f83-rcp-coexistence')],
['Une CK normale permet-elle d’ignorer une faiblesse objective ?',p('Non, le clinicien poursuit une démarche musculaire adaptée si l’examen reste anormal.','dgn83-laboratoire','p83-myofascial-fibro'),p('Certaines myosites peuvent présenter une imagerie anormale malgré des enzymes normales ; les résultats s’interprètent ensemble.','dgn83-imagerie')],
['Une douleur aiguë avec urine foncée après effort attend-elle le prochain contrôle ?',p('Non, le clinicien organise une évaluation urgente de la rhabdomyolyse suspectée et de ses complications.','p83-rhabdo-clinique','p83-rhabdo-menace'),p('La menace rénale ou électrolytique précède la démarche d’un syndrome douloureux chronique.','p83-rhabdo-menace')],
['La duloxétine possède-t-elle une AMM suisse de fibromyalgie dans la spécialité citée ?',p('Non, la liste AIPS comprend notamment dépression, anxiété généralisée et douleur neuropathique diabétique, mais pas fibromyalgie.','aips-f83-dulox-indications'),p('Une utilisation pour la seule fibromyalgie reste hors AMM suisse, même lorsqu’une recommandation européenne en discute l’efficacité.','aips-f83-dulox-indications','f83-has-antidepresseurs')],
['Une dose AIPS d’anxiété devient-elle automatiquement une dose autorisée de fibromyalgie ?',p('Non, le clinicien garde le schéma dans son indication d’origine et n’invente pas une posologie AIPS spécifique du syndrome.','aips-f83-dulox-indications','aips-f83-dulox-posologie'),p('Le statut réglementaire et l’efficacité discutée par une recommandation répondent à des questions différentes.','aips-f83-dulox-indications','f83-has-principes-med')],
['Une faible clairance rénale permet-elle simplement de diminuer la duloxétine ?',p('La spécialité est contre-indiquée lorsque la clairance de créatinine est inférieure à 30 mL/min.','aips-f83-dulox-contre-indications'),p('Une contre-indication ne se remplace pas par une réduction de dose improvisée.','aips-f83-dulox-contre-indications')],
['Le gadolinium est-il permis à toute mère allaitante ?',p('Non, l’ESUR demande de ne pas l’administrer à une mère enceinte ou allaitante ayant une atteinte rénale.','pa82-esur-mere-renale'),p('La possibilité habituelle de poursuivre l’allaitement après un produit macrocyclique ne supprime pas cette restriction.','pa82-esur-allaitement','pa82-esur-mere-renale')],
['Une amélioration de la douleur dispense-t-elle du suivi ?',p('Non, le suivi reprend le fonctionnement, la qualité de vie, l’humeur, la sécurité des traitements et les symptômes nouveaux.','f83-has-suivi','f83-has-differentiel','f83-has-principes-med'),p('La réponse thérapeutique ne prouve pas une guérison biologique ni l’absence future d’une autre maladie.','f83-rcp-coexistence','f83-rcp-fluctuation')]])
save(t)
